const incoming = ($json.body && typeof $json.body === 'object') ? $json.body : $json;

const targetCalendars = new Set(['cameron-1on1-30min']);
const calendarCandidates = [
  incoming.calendarSlug,
  incoming.calendar_slug,
  incoming.calendarId,
  incoming.calendar_id,
  incoming.calendarName,
  incoming.calendar,
  incoming.calendar_name,
  incoming.appointmentCalendar,
  incoming.appointment_calendar,
  incoming.selectedCalendar,
  incoming.selected_calendar,
]
  .map((value) => String(value || '').trim())
  .filter(Boolean);

const matchedCalendar = calendarCandidates.find((value) => targetCalendars.has(value.toLowerCase()));
if (!matchedCalendar) {
  return [];
}

const firstName = String(incoming.firstName || incoming.first_name || '').trim();
const lastName = String(incoming.lastName || incoming.last_name || '').trim();
const fullName = [firstName, lastName].filter(Boolean).join(' ') || 'Unknown contact';
const email = String(incoming.email || '').trim() || 'N/A';
const phone = String(incoming.phone || '').trim() || 'N/A';

const startRaw = incoming.appointmentStart || incoming.bookingStart || incoming.startTime || incoming.start || incoming.appointment_start || '';
const endRaw = incoming.appointmentEnd || incoming.bookingEnd || incoming.endTime || incoming.end || incoming.appointment_end || '';
const calendarName = String(incoming.calendarName || incoming.calendar || incoming.calendar_name || matchedCalendar).trim() || matchedCalendar;
const appointmentTitle = String(incoming.appointmentTitle || incoming.title || incoming.appointment_title || '').trim() || 'N/A';
const timezone = String(incoming.timezone || incoming.tz || 'UTC').trim();

const formatDate = (value) => {
  if (!value) return 'N/A';
  const dt = new Date(value);
  if (Number.isNaN(dt.getTime())) return String(value);
  try {
    return dt.toLocaleString('en-US', { timeZone: timezone, dateStyle: 'medium', timeStyle: 'short' });
  } catch {
    return dt.toISOString();
  }
};

const startAt = formatDate(startRaw);
const endAt = formatDate(endRaw);

const text = [
  'New booking received (#leads)',
  `Name: ${fullName}`,
  `Email: ${email}`,
  `Phone: ${phone}`,
  `Calendar: ${calendarName}`,
  `Appointment: ${appointmentTitle}`,
  `Start: ${startAt}`,
  `End: ${endAt}`,
  `Timezone: ${timezone}`
].join('\n');

return [{
  json: {
    text,
    sourcePayload: incoming
  }
}];

